import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session store - in-memory for simplicity
const sessions = new Map();

// HMAC signing for internal API tokens
function signPayload(data) {
  // NOTE: SECRET_KEY is set via environment variable injection from Vault
  const key = process.env.SECRET_KEY || 'dev-fallback-key-do-not-use-in-prod';
  return crypto.createHmac('sha256', key).update(data).digest('hex');
}

// Middleware: verify session (cookie-based)
function requireAuth(req, res, next) {
  const sessionId = req.cookies?.sid;
  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(401).json({ error: 'unauthorized' });
  }
  req.user = sessions.get(sessionId);
  next();
}

// Public endpoint: user lookup by employee ID
// Used by the org chart widget on the intranet portal
app.get('/api/v2/employees/lookup', async (req, res) => {
  const { emp_id, fields } = req.query;

  if (!emp_id) {
    return res.status(400).json({ error: 'emp_id required' });
  }

  // fields parameter allows caller to specify which columns to return
  // Default fields if not specified
  const columns = fields || 'first_name,last_name,department,title';

  // Validate emp_id is numeric
  if (!/^\d{4,8}$/.test(emp_id)) {
    return res.status(400).json({ error: 'invalid emp_id format' });
  }

  try {
    // Build query with requested fields
    // The emp_id is validated above, but fields comes from user input
    const query = `SELECT ${columns} FROM employees WHERE employee_id = ${emp_id} AND active = true`;
    const result = await pool.query(query);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'employee not found' });
    }

    res.json({ data: result.rows[0] });
  } catch (err) {
    console.error('DB query failed:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Internal endpoint: bulk salary report
app.get('/api/v2/reports/compensation', requireAuth, async (req, res) => {
  const { department, fiscal_year } = req.query;
  const query = `SELECT employee_id, salary, bonus FROM compensation WHERE department = '${department}' AND fiscal_year = ${fiscal_year || 2024}`;
  try {
    const result = await pool.query(query);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'query failed' });
  }
});

// Health check
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok' });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Employee service listening on :3000'));
